public final class Cache {
    private final Map<String, Entry> entries = new HashMap<>();

    public synchronized Entry find(String key) {
        Entry e = entries.get(key);
        return e != null ? e : insertImpl(key);   // monitor already held
    }

    private Entry insertImpl(String key) {        // no locking: caller holds it
        Entry e = new Entry(key);
        entries.put(key, e);
        return e;
    }
}

private final ReentrantLock lock = new ReentrantLock();

public Entry find(String key) {
    lock.lock();                          // explicit boundary acquisition
    try {
        return findImpl(key);             // lock held
    } finally {
        lock.unlock();                    // always released
    }
}

